/bin/bash -lc "python3 - <<'PY'
import ast,copy,hashlib,importlib.util,json,subprocess
from pathlib import Path
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
p=json.loads(Path('proposal.json').read_text())
# Validate the complete supplied study schema without installing packages.
def validate(value,schema,path='"'$'"'):
 typ=schema.get('type')
 if typ=='object':
  assert isinstance(value,dict),(path,'object required')
  assert all(k in value for k in schema.get('required',[])),(path,'missing key')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False:
   assert set(value)<=set(props),(path,'unknown keys',set(value)-set(props))
  for k,v in value.items():
   if k in props:validate(v,props[k],path+'.'+k)
 elif typ=='array':
  assert isinstance(value,list),(path,'array required')
  assert len(value)>=schema.get('minItems',0),(path,'too few items')
  for i,v in enumerate(value):validate(v,schema.get('items',{}),path+f'[{i}]')
 elif typ=='string':
  assert isinstance(value,str),(path,'string required')
  assert len(value)>=schema.get('minLength',0),(path,'short string')
 if 'enum' in schema:assert value in schema['enum'],(path,'invalid enum')
 if 'const' in schema:assert value==schema['const'],(path,'invalid constant')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
allowed_imports={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
normalized=[];cells=set()
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert v['role'] in {'candidate','control'}
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 source=Path(v['file']).read_text();tree=ast.parse(source,filename=v['file'])
 compile(tree,v['file'],'exec')
 for node in ast.walk(tree):
  if isinstance(node,ast.Import): assert all(a.name.split('.')[0] in allowed_imports for a in node.names)
  if isinstance(node,ast.ImportFrom):assert node.module.split('.')[0] in allowed_imports
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name): assert node.func.id not in {'open','eval','exec','__import__'}
 config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert ast.literal_eval(config_node.value)==v['config']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 init=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for key,value in v['config'].items():
  default=ast.literal_eval(defaults[key])
  if isinstance(default,tuple):default=list(default)
  assert default==value,(v['name'],key)
 cells.add((v['config']['slot_mode'],v['config']['representation_mode']))
 # Apart from literal CONFIG/default choices, every arm has identical source.
 config_node.value=ast.parse('None',mode='eval').body
 for key in ('slot_mode','representation_mode'):
  defaults[key].value='NORMALIZED'
 normalized.append(ast.dump(tree,include_attributes=False))
 digest=hashlib.sha256(source.encode()).hexdigest()
 v['note']+=' Source SHA256 '+digest+'.'
 print(v['name'],len(source.splitlines()),'lines',digest)
assert len(set(normalized))==1,'Uncontrolled source difference across factorial arms'
assert cells=={('recency','grouped'),('recency','replicas'),('pooled','grouped'),('pooled','replicas')}
assessment_ids={a['knowledge_id'] for a in p['knowledge_assessments']}
assert set(r['context']['latest_knowledge_usage']['retrieved_ids'])<=assessment_ids
assert {'unirank-method-longer','unirank-method-hiformer','unirank-method-rankmixer','unirank-method-tokenformer'}<=assessment_ids
for a in p['knowledge_assessments']:
 assert a['decision'] in {'used','considered','rejected','unresolved'}
 assert set(a['variant_names'])<=set(v['name'] for v in p['variants'])
print('Study schema, protocol/evidence IDs, source compilation/import boundary, CONFIG/default parity and complete factorial: PASS')
print('Exact normalized source equality across four cells: PASS')
print('New estimated parameters:',32452293+10*32*(4*128+1),'dense',659077+10*32*(4*128+1))
print('Torch available for execution:',importlib.util.find_spec('torch') is not None)
print('Forward/backward and numerical masking checks remain host gates; no training invoked.')
Path('proposal.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\\n')
PY"

